element_query_draft:
(function_definition
  name: (name) @func_name) @function
(method_declaration
  name: (name) @method_name) @function
(class_declaration
  name: (name) @class_name) @class
(interface_declaration
  name: (name) @class_name) @class
(trait_declaration
  name: (name) @class_name) @class
(enum_declaration
  name: (name) @class_name) @class

// Node kinds, confirmed in php/src/node-types.json:
// function_definition  -> field name: name (type name), kind for top-level functions
// method_declaration   -> field name: name (type name), kind for class/trait/enum methods
// class_declaration    -> field name: name (type name)
// interface_declaration-> field name: name (type name)
// trait_declaration    -> field name: name (type name)
// enum_declaration     -> field name: name (type name)

